/****************************************************************************
 * Name: nuttx_enter_critical
 *
 * Description:
 *   Enter a critical section.
 *
 * Input Parameters:
 *   lock - Spinlock (if OS_SPINLOCK == 1).
 *
 ****************************************************************************/

nooptimiziation_function
#if OS_SPINLOCK == 1
void nuttx_enter_critical(FAR rspinlock_t *lock)
#else
void nuttx_enter_critical(void)
#endif
{
  irqstate_t flags;
  int cpu;

  /* Interrupts may already be disabled (if this function is called in nested
   * manner). However, there's no atomic operation that will allow us to
   * check, thus we have to disable interrupts again anyways.
   *
   * However, if this is call is NOT nested (i.e., the first call to enter a
   * critical section), we will save the previous interrupt level so that the
   * saved level can be restored on the last call to exit the critical.
   */

  flags = up_irq_save();

#ifdef CONFIG_IDF_TARGET_ARCH_RISCV
  __asm__ __volatile__("csrr %0, mhartid" : "=r"(cpu));
#else
  cpu = this_cpu();
#endif

  if (g_int_flags_count[cpu] == 0)
    {

      /* If this is the first entry to a critical section. Save the old
       * interrupt level.
       */

      g_int_flags[cpu] = flags;
    }

#if OS_SPINLOCK == 1
#  ifdef CONFIG_SPINLOCK
  /* Spinlocks depend on per-CPU state that does not exist before the
   * scheduler starts; interrupts are already disabled at this point.
   */

  if (OSINIT_OS_READY())
    {
      rspin_lock(lock);
    }
#  endif
#endif

  g_int_flags_count[cpu]++;
}

/****************************************************************************
 * Name: nuttx_exit_critical
 *
 * Description:
 *   Exit a critical section.
 *
 * Input Parameters:
 *   lock - Spinlock (if OS_SPINLOCK == 1).
 *
 ****************************************************************************/

nooptimiziation_function
#if OS_SPINLOCK == 1
void nuttx_exit_critical(FAR rspinlock_t *lock)
#else
void nuttx_exit_critical(void)
#endif
{
  int cpu;

#ifdef CONFIG_IDF_TARGET_ARCH_RISCV
  __asm__ __volatile__("csrr %0, mhartid" : "=r"(cpu));
#else
  cpu = this_cpu();
#endif

  g_int_flags_count[cpu]--;

#if OS_SPINLOCK == 1
#  ifdef CONFIG_SPINLOCK
  if (OSINIT_OS_READY())
    {
      rspin_unlock(lock);
    }
#  endif
#endif

  if (g_int_flags_count[cpu] == 0)
    {
      up_irq_restore(g_int_flags[cpu]);
    }
}

